/* ---------- Publication decision (spec §5.3) — recomputed from live state, never a stored boolean ---------- */
export function subEligible(sub) {
  if (!sub) return false
  if (sub.status === 'active' || sub.status === 'grace') return true
  if (sub.status === 'cancelled') return true // eligible until the paid period ends
  return false
}
export function verOk(c, v) {
  if (!c.verifyReq) return true
  if (v.ver !== 'approved') return false
  // only the credentials this category actually requires can block it (SC-009: the affected listing is hidden)
  return !v.docs.some((d) => c.docs.includes(d.name) && ['expired', 'rejected', 'missing'].includes(d.status))
}
export function gatesFor(l, v) {
  const c = cat(l.cat)
  const fieldsOk = !!l.title && (l.desc || '').trim().length >= 20 && l.areas?.length > 0 && c.active !== false
  const reviewTxt = { approved: 'Content review approved', pending: 'Content review pending', changes: 'Reviewer asked for changes', rejected: 'Content review rejected', draft: 'Not submitted for review' }[l.review]
  const verFail = v.ver === 'approved' ? 'A required document has expired or is missing' : { not_started: 'No verification evidence submitted', submitted: 'Verification awaiting review', more_info: 'More information required', rejected: 'Verification rejected', expired: 'Credential expired', revoked: 'Approval revoked' }[v.ver]
  return [
    { id: 'acct', label: 'Vendor account in a permitted state', ok: v.acct === 'active', detail: v.acct === 'active' ? 'Account is active' : `Account is ${v.acct}`, fix: v.acct === 'pending' ? 'Complete verification' : 'Contact support', who: 'Account' },
    { id: 'review', label: 'Listing approved by content review', ok: l.review === 'approved' && !l.paused && !l.restricted, detail: l.restricted ? 'Listing is restricted' : l.paused ? 'Listing is paused by you' : reviewTxt, fix: l.paused ? 'Resume the listing' : l.review === 'rejected' || l.review === 'changes' ? 'Fix the issues and resubmit' : l.review === 'draft' ? 'Submit for review' : 'Wait for the reviewer', who: 'Content review' },
    { id: 'sub', label: 'Subscription active or in grace period', ok: subEligible(v.sub), detail: v.sub.status === 'grace' ? `Grace period — visible until ${v.sub.grace}` : v.sub.status === 'cancelled' ? `Auto-renew off — eligible until ${v.sub.paidUntil}` : v.sub.status === 'active' ? `Paid until ${v.sub.paidUntil}` : v.sub.status === 'expired' ? 'Subscription expired after the grace period' : 'No paid plan — free accounts cannot publish', fix: 'Renew or choose a plan', who: 'Subscription' },
    { id: 'ver', label: c.verifyReq ? 'Required category verification valid' : 'Category needs no document verification', ok: verOk(c, v), detail: c.verifyReq ? (verOk(c, v) ? 'Approved and not expired' : verFail) : 'Not required for this category', fix: 'Update verification documents', who: 'Verification' },
    { id: 'fields', label: 'Required fields & service area present', ok: fieldsOk, detail: fieldsOk ? 'Complete' : c.active === false ? 'This category was deactivated or merged' : 'Title, description (20+ chars) and at least one service area are required', fix: 'Complete the listing', who: 'Listing' },
    { id: 'hold', label: 'No legal, fraud, safety or admin hold', ok: !l.hold && !v.hold, detail: l.hold || v.hold || 'No hold', fix: 'Contact support', who: 'Trust & Safety' },
  ]
}
export const isPublished = (l, v) => !!v && gatesFor(l, v).every((g) => g.ok)
export const firstBlocker = (l, v) => gatesFor(l, v).find((g) => !g.ok)

/* service-area match (spec §7.1): never imply every vendor serves all of India */
/* coverage scopes: city (default, with optional pincodes) · country · global */
export const serves = (l, loc) => {
  const sc = l.scope || 'city'
  if (sc === 'global' || l.remote) return true
  if (sc === 'country') return (l.countries || ['IN']).includes(loc.country || 'IN')
  return (loc.country || 'IN') === 'IN' && l.areas.includes(loc.city) && (!l.pins || l.pins.includes(loc.pin))
}

/* coverage labels used by the Explore filter: local / remote / national / international */
export const coverageOf = (l) => {
  const out = []
  const sc = l.scope || 'city'
  if (sc === 'city') out.push('local')
  if (l.remote) out.push('remote')
  if (sc === 'country') out.push('national')
  if (sc === 'global' || (sc === 'country' && (l.countries || []).length > 1)) out.push('international')
  return out
}

